import { runTestBuild } from "./TestBuilder.js"
import { Option, program } from "commander"

await program
	.addOption(new Option("-i, --integration", "Include integration tests (requires local tutadb server)"))
	.addOption(new Option("-c, --clean"))
	.addOption(new Option("-f, --filter <query>", "Filter for tests and specs to run only matching tests"))
	.addOption(new Option("--no-run", "Do not run the tests in node"))
	.addOption(new Option("-br, --browser", "Start the web server and run the tests in browser").default(false))
	.addOption(new Option("--browser-cmd <path>", "Command used to run the browser").default("xdg-open"))
	.action(async ({ clean, integration, filter, run, browser, browserCmd }) => {
		await runTestBuild({ clean })
		console.log("build finished!")

		let nodeOk
		if (run) {
			nodeOk = await runTestsInNode({ integration, filter })
		} else {
			nodeOk = true
		}

		let browserOk
		if (browser) {
			browserOk = await runTestsInBrowser({ filter, browserCmd })
		} else {
			browserOk = true
		}

		if (browserOk && nodeOk) {
			process.exit(0)
		} else {
			process.exit(1)
		}
	})
	.parseAsync(process.argv)

function resultIsOk(result) {
	return result.failingTests.length === 0
}

/** Function which runs tests and exits with the exit code afterwards. */
async function runTestsInBrowser({ filter, browserCmd }) {
	const { default: express } = await import("express")
	const app = express()
	app.use(express.static("build"))
	// deafault limit (100Kb) is way too small
	app.use(express.json({ limit: "10Mb" }))

	const result = await new Promise(async (resolve) => {
		app.post("/status", (req, res) => {
			console.log("browser: ", req.body)
			res.status(200).send()
		})
		app.post("/result", (req, res) => {
			resolve(req.body)
			res.status(200).send()
		})

		const server = await new Promise(async (resolve) => {
			const s = app.listen(0, () => resolve(s))
		})

		const url = new URL(`http://localhost:${server.address().port}/test.html`)
		if (filter) {
			url.searchParams.set("filter", filter)
		}

		const { spawn } = await import("node:child_process")
		const command = `${browserCmd} '${url.toString()}'`
		console.log(`> ${command}`)
		spawn(command, { stdio: "inherit", shell: true })
	})

	const { default: o } = await import("@tutao/otest")
	console.log("\n--------------- BROWSER ---------------")
	o.printReport(result)
	return resultIsOk(result)
}

async function runTestsInNode({ integration, filter }) {
	const { run } = await import("./build/testInNode.js")
	console.log("\n--------------- NODE ---------------")
	const result = await run({ integration, filter })
	return resultIsOk(result)
}
import * as env from "../buildSrc/env.js"
import fs from "fs-extra"
import path from "node:path"
import { renderHtml } from "../buildSrc/LaunchHtml.js"
import { build as esbuild } from "esbuild"
import { getTutanotaAppVersion, runStep, sh, writeFile } from "../buildSrc/buildUtils.js"
import { aliasPath as esbuildPluginAliasPath } from "esbuild-plugin-alias-path"
import { keytarNativePlugin, libDeps, preludeEnvPlugin, sqliteNativePlugin } from "../buildSrc/esbuildUtils.js"
import { buildPackages } from "../buildSrc/packageBuilderFunctions.js"
import watPlugin from "esbuild-plugin-wat"

export async function runTestBuild({ clean, fast = false }) {
	if (clean) {
		await runStep("Clean", async () => {
			await fs.emptyDir("build")
		})
	}

	if (!fast) {
		await runStep("Packages", async () => {
			await buildPackages("..")
		})

		await runStep("Types", async () => {
			await sh`npx tsc --incremental true --noEmit true`
		})
	}

	const version = getTutanotaAppVersion()
	const localEnv = env.create({ staticUrl: "http://localhost:9000", version, mode: "Test", dist: false })

	await runStep("Assets", async () => {
		const pjPath = path.join("..", "package.json")
		await fs.mkdir(inBuildDir(), { recursive: true })
		await fs.copyFile(pjPath, inBuildDir("package.json"))
		await fs.copyFile(path.join("..", "packages/tutanota-crypto/lib/hashes/Argon2id/argon2.wasm"), inBuildDir("argon2.wasm"))
		await createUnitTestHtml(localEnv)
	})
	await runStep("Esbuild", async () => {
		await esbuild({
			entryPoints: ["tests/testInBrowser.ts", "tests/testInNode.ts"],
			outdir: "./build",
			// Bundle to include the whole graph
			bundle: true,
			// Split so that dynamically included node-only tests are not embedded/run in the browser
			splitting: true,
			format: "esm",
			sourcemap: "linked",
			target: "esnext",
			define: {
				// See Env.ts for explanation
				NO_THREAD_ASSERTIONS: "true",
			},
			external: [
				"electron",
				// esbuild can't deal with node imports in ESM output at the moment
				// see https://github.com/evanw/esbuild/pull/2067
				"xhr2",
				"better-sqlite3",
				"express",
				"server-destroy",
				"body-parser",
				"jsdom",
			],
			// even though tests might be running in browser we set it to node so that it ignores all builtins
			platform: "node",
			plugins: [
				preludeEnvPlugin(localEnv),
				libDeps(".."),
				esbuildPluginAliasPath({
					alias: {
						// Take browser testdouble without funny require() magic
						testdouble: path.resolve("../node_modules/testdouble/dist/testdouble.js"),
					},
				}),
				sqliteNativePlugin({
					environment: "node",
					// We put it back into node_modules because we don't bundle it. If we remove node_modules but keep the cached one we will not run build.
					dstPath: "../node_modules/better-sqlite3/build/Release/better_sqlite3.node",
					platform: process.platform,
					// Since we don't bundle it we need to give a path relative to database.js in node_modules/better_sqlite3
					nativeBindingPath: "../build/Release/better_sqlite3.node",
				}),
				keytarNativePlugin({
					environment: "node",
					dstPath: "./build/keytar.node",
					platform: process.platform,
				}),
				watPlugin({
					loader: "file",
				}),
			],
		})
	})
}

async function createUnitTestHtml(localEnv) {
	const imports = [{ src: `./testInBrowser.js`, type: "module" }]
	const htmlFilePath = inBuildDir("test.html")

	console.log(`Generating browser tests at "${htmlFilePath}"`)

	const html = await renderHtml(imports, localEnv)
	await writeFile(htmlFilePath, html)
}

function inBuildDir(...files) {
	return path.join("build", ...files)
}

